import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;
  const node = new Group();

  // Geometry: unit plane (will be scaled by config.sceneScale if provided)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, map: null });
  const mesh = new Mesh(geometry, material);
  node.add(mesh);

  // Load texture if an image URL is supplied
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply rotation and scale from config (position is handled by the adapter)
  if (config.sceneRotation && Array.isArray(config.sceneRotation)) {
    const [rx, ry, rz] = config.sceneRotation;
    node.rotation.set(rx, ry, rz);
  }
  if (config.sceneScale && Array.isArray(config.sceneScale)) {
    const [sx, sy, sz] = config.sceneScale;
    node.scale.set(sx, sy, sz);
  }

  // No cinematic primitives for this node
  node.userData.primitives = [];

  // Event handlers container (empty as no interactions are defined)
  node.userData.handlers = {};

  // Cleanup routine
  node.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();
    // Cancel any GSAP timelines that might have been created (none for this node)
    // (placeholder for future timelines)
    if (node.userData._timelines) {
      node.userData._timelines.forEach((tl) => tl.kill());
    }
    // Cleanup primitives if any were added in the future
    if (node.userData.primitives) {
      node.userData.primitives.forEach((p) => {
        if (p && typeof p.cleanup === 'function') p.cleanup();
      });
    }
  };

  return node;
}
